class _Ledger:
    def __init__(self, balances, fee):
        self.FEE = fee
        self.balances = dict(balances)
        self.log = []
    def lock(self, a): self.log.append(("lock", a))
    def unlock(self, a): self.log.append(("unlock", a))
    def balance(self, a): return self.balances[a]
    def debit(self, a, n):
        self.log.append(("debit", a, n)); self.balances[a] -= n
    def credit(self, a, n):
        self.log.append(("credit", a, n)); self.balances[a] += n

def check(candidate):
    l = _Ledger({"zeta": 1000, "alpha": 0}, fee=5)
    assert candidate(l, "zeta", "alpha", 100) is True
    assert l.log == [("lock", "alpha"), ("lock", "zeta"), ("debit", "zeta", 105),
                     ("credit", "alpha", 100), ("unlock", "zeta"), ("unlock", "alpha")]
    assert l.balances == {"zeta": 895, "alpha": 100}
    l2 = _Ledger({"a": 104, "b": 0}, fee=5)
    assert candidate(l2, "a", "b", 100) is False
    assert l2.log == [("lock", "a"), ("lock", "b"), ("unlock", "b"), ("unlock", "a")]
    assert l2.balances == {"a": 104, "b": 0}
    l3 = _Ledger({"a": 105, "b": 0}, fee=5)
    assert candidate(l3, "a", "b", 100) is True
    assert l3.balances == {"a": 0, "b": 100}
